'use strict';
// Educational model, not a database of experimentally measured Rf constants.
const CH_COMPOUNDS=[
 {id:'aspirin',name:'Aspirin',formula:'C₉H₈O₄',rf:.62,color:'#bd7044',note:'Acetylsalicylic acid; carboxylic acid and ester groups.'},
 {id:'paracetamol',name:'Paracetamol',formula:'C₈H₉NO₂',rf:.34,color:'#318d87',note:'Also called acetaminophen; phenol and amide groups.'},
 {id:'caffeine',name:'Caffeine',formula:'C₈H₁₀N₄O₂',rf:.16,color:'#8b65b0',note:'Multiple nitrogen and carbonyl sites interact with silica.'},
 {id:'ibuprofen',name:'Ibuprofen',formula:'C₁₃H₁₈O₂',rf:.80,color:'#5375b4',note:'Carboxylic acid with a substantial hydrophobic carbon framework.'}
];
const CH_UNKNOWNS={A:['aspirin','caffeine'],B:['paracetamol','caffeine'],C:['ibuprofen'],D:['aspirin','paracetamol','caffeine']};
const ch={fraction:1,solvent:'ea',sample:'unknown',unknown:'A',custom:['aspirin','paracetamol'],mixLane:5,co:'aspirin',lanes:Array.from({length:7},()=>null),progress:0,running:false,uv:true,colors:false,speed:1,spotting:-1,selected:null,revealed:false,guess:[],feedback:'',message:'Choose a sample, then click a lane at the pencil baseline to spot it.',history:[],timer:0};
try{ch.history=JSON.parse(localStorage.getItem('simlab-chromatography-history')||'[]').slice(-12)}catch{}
function chRf(id,fraction=ch.fraction){let r=CH_COMPOUNDS.find(c=>c.id===id).rf;let k=(1-r)/r;return 1/(1+k*Math.exp(4*(1-fraction)))}
function chSolvent(){return `${Math.round((1-ch.fraction)*100)}:${Math.round(ch.fraction*100)} hexane / ethyl acetate (v/v)`}
function chOptions(){return CH_COMPOUNDS.map(c=>`<option value="${c.id}" ${ch.sample===c.id?'selected':''}>${c.name} standard</option>`).join('')}
function chChoices(which,values){return CH_COMPOUNDS.map(c=>`<label class="ch-check"><input type="checkbox" data-ch-${which}="${c.id}" ${values.includes(c.id)?'checked':''}>${c.name}</label>`).join('')}
function chromatography(){return `${head('SEPARATION SCIENCE','Chromatography','Spot a sample. Watch the solvent rise. Compare an unknown with authentic standards on the same silica plate.')}<div class="ch-grid"><aside class="ch-controls"><section class="panel ch-card"><span class="ch-tag">01 · MOBILE PHASE</span><h2>Developing solvent</h2><label class="ch-field">Stationary phase<select disabled aria-label="Stationary phase"><option>Silica gel TLC · UV254 plate</option></select></label><label class="ch-field">Solvent system<select id="chSolvent" ${ch.progress>0?'disabled':''}><option value="ea" ${ch.solvent==='ea'?'selected':''}>Ethyl acetate · reference system</option><option value="balanced" ${ch.solvent==='balanced'?'selected':''}>Hexane : ethyl acetate · 40:60</option><option value="weak" ${ch.solvent==='weak'?'selected':''}>Hexane : ethyl acetate · 80:20</option><option value="hexane" ${ch.solvent==='hexane'?'selected':''}>Hexane · weak eluent</option><option value="custom" ${ch.solvent==='custom'?'selected':''}>Mix my own solvent</option></select></label>${ch.solvent==='custom'?`<label class="ch-field">Ethyl acetate: <b id="chPercent">${Math.round(ch.fraction*100)}% v/v</b><input id="chFraction" type="range" min="0" max="100" value="${Math.round(ch.fraction*100)}" ${ch.progress>0?'disabled':''}></label>`:''}<div class="ch-note">${chSolvent()}<br>Total blend: 10 mL = ${(10*(1-ch.fraction)).toFixed(1)} mL hexane + ${(10*ch.fraction).toFixed(1)} mL ethyl acetate.</div><p>On this normal-phase model, more ethyl acetate increases solvent strength and migration. A weak solvent leaves some spots near the origin.</p></section><section class="panel ch-card"><span class="ch-tag">02 · SAMPLE PREPARATION</span><h2>Mix &amp; spot</h2><label class="ch-field">Coded sample<select id="chUnknown">${Object.keys(CH_UNKNOWNS).map(k=>`<option ${k===ch.unknown?'selected':''}>${k}</option>`).join('')}</select></label><div class="ch-actions">${Object.keys(CH_UNKNOWNS).map(k=>`<button class="btn ${ch.unknown===k&&ch.sample==='unknown'?'soft':'secondary'} small" data-ch-action="unknown-${k}">Load unknown ${k}</button>`).join('')}</div><p>Load any coded unknown, then spot a different lane. A, B, C and D can share the same plate. After development, select a code to identify that unknown.</p><label class="ch-field">Load capillary with<select id="chSample" ${ch.progress>0?'disabled':''}>${chOptions()}<option value="allstandards" ${ch.sample==='allstandards'?'selected':''}>All 4 standards mixture · one spot</option><option value="unknown" ${ch.sample==='unknown'?'selected':''}>Unknown ${ch.unknown}</option><option value="custom" ${ch.sample==='custom'?'selected':''}>My mixture</option><option value="cospot" ${ch.sample==='cospot'?'selected':''}>Unknown + selected standard (co-spot)</option></select></label><details open><summary>Make my mixture</summary>${chChoices('mix',ch.custom)}${Object.keys(CH_UNKNOWNS).map(k=>`<label class="ch-check"><input type="checkbox" data-ch-mix="U:${k}" ${ch.custom.includes('U:'+k)?'checked':''}>Unknown ${k}</label>`).join('')}<p>Combine standards and coded unknown solutions in equal relative amounts. Components from unknown solutions stay unnamed until you compare them with standards. Tick the substances to combine, choose a lane below, then click Spot mixture.</p><label class="ch-field">Mixture destination<select id="chMixLane" ${ch.progress>0?'disabled':''}>${ch.lanes.map((l,i)=>`<option value="${i}" ${ch.mixLane===i?'selected':''}>Lane ${i+1} · ${l?l.label+' (replace)':'empty'}</option>`).join('')}</select></label><button class="btn" data-ch-action="spot-mixture" ${ch.progress>0||ch.spotting>=0?'disabled':''}>Spot mixture</button><p>The selected substances are deposited together at one point. Develop the plate to see them separate.</p></details><label class="ch-field">Co-spot standard<select id="chCo">${CH_COMPOUNDS.map(c=>`<option value="${c.id}" ${c.id===ch.co?'selected':''}>${c.name}</option>`).join('')}</select></label><div class="ch-actions"><button class="btn soft small" data-ch-action="standards" ${ch.progress>0?'disabled':''}>Spot standards separately</button><button class="btn secondary small" data-ch-action="demo">Load example plate</button></div><p>To separate all four standards from one spot, choose “All 4 standards mixture” above, then spot one lane. Click one of the seven lanes at the baseline. A fresh capillary deposits a small spot; it dries before development. Re-spot a lane to replace its sample.</p></section><section class="panel ch-card"><span class="ch-tag">READ THE PLATE</span><h2>Viewing &amp; measurement</h2><label class="ch-check"><input id="chUV" type="checkbox" ${ch.uv?'checked':''}>UV254 visualization</label><label class="ch-check"><input id="chColors" type="checkbox" ${ch.colors?'checked':''}>Teaching colors &amp; molecule markers</label><p>These analgesics are colorless. UV reveals dark absorbing spots on a fluorescent plate. Teaching colors and moving dots are explanatory overlays, not visible molecular trajectories.</p><div class="ch-callout">Rf = distance from baseline to spot center ÷ distance from baseline to solvent front. Both distances use the same baseline.</div><p>The pencil baseline is 1 cm above the bottom, above the solvent reservoir. The final solvent-front distance is 7.00 cm.</p></section></aside><div><section class="panel ch-card"><div class="ch-status"><div><span class="ch-tag">SILICA TLC · ASCENDING DEVELOPMENT</span><h2 style="margin:6px 0">The developing chamber</h2></div><span class="pill">${ch.running?'DEVELOPING':ch.progress===1?'PLATE COMPLETE':ch.progress>0?'PAUSED':'READY TO SPOT'}</span></div><div id="chStage" class="ch-stage">${chPlate()}</div><div class="ch-status"><span id="chFront">Solvent front: ${(7*ch.progress).toFixed(2)} cm</span><progress id="chProgress" value="${ch.progress}" max="1" aria-label="Development progress"></progress></div><div class="ch-actions" aria-label="Spot a lane">${ch.lanes.map((l,i)=>`<button class="btn secondary small" data-ch-lane="${i}" ${ch.progress>0||ch.spotting>=0?'disabled':''}>Spot lane ${i+1}</button>`).join('')}</div><div class="ch-actions"><button class="btn" data-ch-action="develop" ${!ch.lanes.some(Boolean)||ch.progress===1||ch.spotting>=0?'disabled':''}>${ch.progress===1?'Development complete':ch.running?'Pause development':ch.progress>0?'Resume development':'Develop plate'}</button><label class="ch-check">Speed <select id="chSpeed"><option value="1" ${ch.speed===1?'selected':''}>1×</option><option value="3" ${ch.speed===3?'selected':''}>3×</option><option value=".5" ${ch.speed===.5?'selected':''}>0.5×</option></select></label><button class="btn secondary" data-ch-action="reset">New plate</button><button class="btn secondary" data-ch-action="save" ${ch.progress!==1?'disabled':''}>Save run</button><button class="btn secondary" data-ch-action="export" ${!ch.history.length?'disabled':''}>Export runs CSV</button></div><div class="ch-note" id="chMessage" role="status" aria-live="polite">${ch.message}</div><div class="ch-legend">${ch.colors?CH_COMPOUNDS.map(c=>`<span><i style="background:${c.color}"></i>${c.name}</span>`).join(''):'<span>● UV-absorbing spot · dashed blue line = solvent front · dotted grey line = pencil baseline</span>'}</div></section><section class="panel ch-card"><span class="ch-tag">03 · COMPARE THE EVIDENCE</span><h2>Distances &amp; retention factors</h2><p>${ch.progress===1?'Click a developed spot to highlight its measurement. Unknown spots are labelled by height, from the baseline upward.':'Complete development to record the final measurements. The solvent front must be marked immediately after removing the plate.'}</p><div id="chReadings">${chReadings()}</div><div class="ch-note">All numerical Rf values here are illustrative model outputs, not published measurements. Rf changes with mobile phase, adsorbent, loading and experimental conditions. Compare standards on the same plate.</div></section><div class="ch-layout-footer"><section class="panel ch-card"><h2>Identify unknown ${ch.unknown}</h2><p>Match each unknown spot with the standards. Try a second solvent and co-spot to strengthen your conclusion.</p>${chChoices('guess',ch.guess)}<div class="ch-actions"><button class="btn small" data-ch-action="check" ${ch.progress!==1||!ch.lanes.some(l=>l?.unknownCode===ch.unknown)?'disabled':''}>Check identification</button><button class="btn secondary small" data-ch-action="reveal">${ch.revealed?'Hide composition':'Reveal composition'}</button></div><div id="chFeedback" role="status">${ch.feedback}</div>${ch.revealed?`<p class="ch-unknown">${CH_UNKNOWNS[ch.unknown].map(id=>CH_COMPOUNDS.find(c=>c.id===id).name).join(' + ')}</p>`:''}<p>Co-migration is consistent with a match; it does not establish identity or purity. Different substances can share an Rf.</p></section><section class="panel ch-card"><h2>How it works</h2><ol><li>Choose a developing solvent and prepare standards and an unknown.</li><li>Spot small, dry deposits above the solvent level.</li><li>Develop in a covered chamber. Solvent rises by capillary action.</li><li>Molecules repeatedly adsorb to silica and dissolve into the moving solvent. Different affinities produce different migration rates.</li><li>Mark the front, visualize, measure, then compare.</li></ol><p>This is thin-layer chromatography. Paper chromatography uses a different stationary-phase system, so these silica results should not be transferred to paper.</p></section></div><section class="panel ch-card"><h2>Run notebook <span class="pill">${ch.history.length} SAVED</span></h2>${ch.history.length?`<div class="ch-scroll"><table class="ch-table"><thead><tr><th>Run</th><th>Solvent (hexane:EA)</th><th>Unknown</th><th>Spots recorded</th></tr></thead><tbody>${ch.history.map((r,i)=>`<tr><td>${i+1}</td><td>${r.ratio}</td><td>${r.unknown}</td><td>${r.readings.length}</td></tr>`).join('')}</tbody></table></div>`:'<p>Develop a plate and save your run to keep its solvent conditions and spot measurements on this device.</p>'}<details class="ch-reference"><summary>Scientific basis, standards &amp; model limits</summary><p>The compound set and the ethyl acetate developing solvent follow the <a href="https://dept.harpercollege.edu/chemistry/wachter/Labs/Thin-Layer%20Chromatography.pdf" target="_blank" rel="noopener">Harper College TLC practical</a>, which uses aspirin, ibuprofen, acetaminophen and caffeine, comparison with standards, UV visualization and co-spotting. Principles and changing solvent strength are discussed in <a href="https://www.jove.com/science-education/v/11208/thin-layer-chromatography-experimental-setup-and-separation-procedure" target="_blank" rel="noopener">JoVE’s TLC practical</a>.</p><p>The sources document the experiment, not the numerical values in this simulator. At 100% ethyl acetate the chosen teaching anchors are caffeine 0.16, paracetamol 0.34, aspirin 0.62 and ibuprofen 0.80. Other compositions use an illustrative solvent-strength relationship: Rf = 1 / [1 + ((1 − r) / r) exp(4(1 − φ))], where r is the teaching anchor and φ is the ethyl acetate volume fraction. This model preserves an educational separation order; it does not predict real samples quantitatively, resolve new substances, simulate acid/base modifiers or reproduce all solvent selectivity effects.</p><p>Development is accelerated and idealized. Spots represent many molecules, not individual molecules. Solvent and sample selection are virtual; laboratory solvent work requires appropriate supervision and handling procedures.</p>${CH_COMPOUNDS.map(c=>`<p><b>${c.name} · ${c.formula}</b> — ${c.note}</p>`).join('')}</details></section></div></div>`}
function chPlate(){let p=ch.progress,base=410,front=base-320*p;return `<svg viewBox="0 0 720 520" role="img" aria-label="Seven-lane thin-layer chromatography plate, solvent front ${(p*7).toFixed(2)} centimeters above baseline"><defs><linearGradient id="chGlass" x2="1" y2="1"><stop stop-color="#ffffff" stop-opacity=".7"/><stop offset="1" stop-color="#c9dfd3" stop-opacity=".35"/></linearGradient><filter id="chBlur"><feGaussianBlur stdDeviation="2.3"/></filter></defs><rect x="52" y="32" width="616" height="454" rx="23" fill="url(#chGlass)" stroke="#a9c1b3" stroke-width="2"/><rect x="43" y="22" width="634" height="20" rx="6" fill="#648a76"/><text x="360" y="65" text-anchor="middle" font-size="12" fill="#54705f">${p===1?'Developed plate · removed, front marked and dried':'Covered developing chamber · 10 mL mobile phase'}</text><rect x="80" y="78" width="560" height="376" rx="3" fill="${ch.uv?'#d1edaa':'#f8f7ed'}" stroke="#9da98f"/><rect x="81" y="${front}" width="558" height="${454-front}" fill="#a6c7a3" opacity=".22"/><rect x="54" y="435" width="612" height="48" rx="14" fill="#7eafbb" opacity="${p===1?0:.23}"/><line x1="80" x2="640" y1="${front}" y2="${front}" stroke="#317d9b" stroke-dasharray="7 4"/><line x1="80" x2="640" y1="410" y2="410" stroke="#788575" stroke-dasharray="3 4"/><text x="12" y="415" font-size="10" fill="#526958">0 cm</text><text x="12" y="95" font-size="10" fill="#526958">7 cm</text><text x="648" y="${Math.max(95,front-5)}" font-size="10" fill="#317d9b">front</text>${Array.from({length:8},(_,i)=>`<line x1="72" x2="80" y1="${410-i*320/7}" y2="${410-i*320/7}" stroke="#819b89"/>`).join('')}${ch.lanes.map((l,i)=>{let x=120+i*80;let spots=l?l.ids.slice().sort((a,b)=>chRf(a)-chRf(b)).map((id,j)=>{let c=CH_COMPOUNDS.find(c=>c.id===id),y=base-320*p*chRf(id),visible=ch.uv||ch.colors,selected=ch.selected===`${i}-${id}`;return `<g class="ch-spot" data-ch-spot="${i}-${id}"><ellipse cx="${x}" cy="${y}" rx="${7+3*p}" ry="${5+5*p}" fill="${ch.colors?c.color:'#3c315a'}" opacity="${visible?(ch.spotting===i?.9:.65):0}" filter="url(#chBlur)"/>${visible?`<ellipse cx="${x}" cy="${y}" rx="${selected?15:9}" ry="${selected?15:9}" fill="transparent" stroke="${selected?'#173c30':'transparent'}" stroke-width="2"/>`:''}${ch.colors?Array.from({length:5},(_,k)=>`<circle cx="${x+(k-2)*3}" cy="${y+Math.sin(k*3+p*20)*4}" r="1.4" fill="white"/>`).join(''):''}<title>Lane ${i+1} · ${l.unknown&&!ch.revealed?'spot '+(j+1):c.name}${p===1?' · Rf '+chRf(id).toFixed(2):''}</title></g>`}).join(''):'';return `<g><rect class="ch-lane" data-ch-lane="${i}" x="${x-36}" y="375" width="72" height="62" tabindex="0" role="button" aria-label="Spot lane ${i+1}${l?', '+l.label:''}"/><text x="${x}" y="467" text-anchor="middle" font-size="10" fill="#395747">${i+1} · ${l?l.label:'empty'}</text>${spots}${ch.spotting===i?`<g class="ch-capillary"><rect x="${x-2}" y="325" width="4" height="82" fill="#e7f5f5" stroke="#588d96"/><circle cx="${x}" cy="409" r="3" fill="#536e72"/></g>`:''}</g>`}).join('')}<text x="360" y="506" text-anchor="middle" font-size="11" fill="#516d5b">${p===0?'Click a lane at the pencil baseline to deposit your sample':p===1?'Front marked · plate removed and dried · click spots to measure':'Solvent rises by capillary action · compounds partition between silica and solvent'}</text></svg>`}
function chRows(){return ch.lanes.flatMap((l,i)=>l?l.ids.slice().sort((a,b)=>chRf(a)-chRf(b)).map((id,j)=>({lane:i+1,label:l.label,spot:l.unknown&&!ch.revealed?`Spot ${j+1}`:CH_COMPOUNDS.find(c=>c.id===id).name,id,rf:chRf(id),distance:7*chRf(id),unknown:l.unknown})):[])}
function chReadings(){if(ch.progress!==1)return '<p class="muted">No final measurements yet.</p>';let rows=chRows();return `<div class="ch-scroll"><table class="ch-table"><thead><tr><th>Lane / sample</th><th>Spot</th><th>Spot distance</th><th>Front distance</th><th>Rf</th><th>Same-plate standard match</th></tr></thead><tbody>${rows.map(r=>{let matches=CH_COMPOUNDS.filter(c=>Math.abs(chRf(c.id)-r.rf)<.025&&ch.lanes.some(l=>l&&!l.unknown&&(l.ids.length===1||l.allStandards)&&l.ids.includes(c.id))).map(c=>c.name);return `<tr class="${ch.selected===`${r.lane-1}-${r.id}`?'ch-selected':''}"><td>${r.lane} · ${r.label}</td><td>${r.spot}</td><td>${r.distance.toFixed(2)} cm</td><td>7.00 cm</td><td><b>${r.rf.toFixed(2)}</b></td><td>${r.unknown?(matches.join(' / ')||'No matching standard spotted'):'Reference / prepared sample'}</td></tr>`}).join('')}</tbody></table></div>`}
function chPaint(){let stage=document.getElementById('chStage');if(!stage)return;stage.innerHTML=chPlate();document.getElementById('chFront').textContent=`Solvent front: ${(7*ch.progress).toFixed(2)} cm`;document.getElementById('chProgress').value=ch.progress}
function chRender(){if(page==='chromatography')render()}
function chReset(){ch.running=false;cancelAnimationFrame(ch.timer);ch.progress=0;ch.lanes=Array.from({length:7},()=>null);ch.spotting=-1;ch.selected=null;ch.feedback='';ch.message='Fresh plate ready. Select a solvent and spot samples above the solvent level.'}
function chSpot(i){if(ch.progress>0||ch.spotting>=0)return;let ids,label,unknown=false;if(ch.sample==='allstandards'){ids=CH_COMPOUNDS.map(c=>c.id);label='All stds'}else if(ch.sample==='unknown'){ids=CH_UNKNOWNS[ch.unknown];label='Unknown '+ch.unknown;unknown=true}else if(ch.sample==='cospot'){ids=[...new Set([...CH_UNKNOWNS[ch.unknown],ch.co])];label='U + '+CH_COMPOUNDS.find(c=>c.id===ch.co).name.slice(0,3);unknown=true}else if(ch.sample==='custom'){ids=[...new Set(ch.custom.flatMap(id=>id.startsWith('U:')?CH_UNKNOWNS[id.slice(2)]:[id]))];unknown=ch.custom.some(id=>id.startsWith('U:'));label='My mix'}else{ids=[ch.sample];label=CH_COMPOUNDS.find(c=>c.id===ch.sample).name.slice(0,3)}if(!ids.length){ch.message='Choose at least one substance for your mixture.';chRender();return}ch.lanes[i]={ids:[...ids],label,unknown,allStandards:ch.sample==='allstandards',unknownCode:ch.sample==='unknown'||ch.sample==='cospot'?ch.unknown:null};ch.spotting=i;ch.message=`Spotting lane ${i+1}: ${label}. Allowing the solvent to evaporate…`;chRender();setTimeout(()=>{if(ch.spotting!==i)return;ch.spotting=-1;ch.message='Spot is dry. Add another sample or develop the plate.';chRender()},850)}
function chDevelop(){if(ch.spotting>=0||!ch.lanes.some(Boolean)||ch.progress===1)return;ch.running=!ch.running;cancelAnimationFrame(ch.timer);if(ch.running)ch.progress=Math.max(ch.progress,.000001);ch.message=ch.running?'The solvent front is rising. Molecules migrate at different rates as they interact with silica and the mobile phase.':'Development paused for inspection.';chRender();if(!ch.running)return;let last=performance.now();function tick(now){if(!ch.running)return;if(page!=='chromatography'){ch.running=false;return}ch.progress=Math.min(1,ch.progress+Math.min(now-last,100)*ch.speed/18000);last=now;chPaint();if(ch.progress===1){ch.running=false;ch.message='Development complete. The plate has been removed, the front marked, and the solvent dried. Inspect under UV and compare unknown spots with standards.';chRender()}else ch.timer=requestAnimationFrame(tick)}ch.timer=requestAnimationFrame(tick)}
document.addEventListener('change',e=>{if(page!=='chromatography')return;let t=e.target;if(t.id==='chMixLane'){ch.mixLane=Number(t.value)}else if(t.id==='chSolvent'&&ch.progress===0){ch.solvent=t.value;ch.fraction=({ea:1,balanced:.6,weak:.2,hexane:0,custom:ch.fraction})[t.value];chRender()}else if(t.id==='chFraction'&&ch.progress===0){ch.fraction=Number(t.value)/100;chRender()}else if(t.id==='chSample'){ch.sample=t.value;chRender()}else if(t.id==='chUnknown'){chLoadUnknown(t.value)}else if(t.id==='chCo'){ch.co=t.value}else if(t.id==='chSpeed'){ch.speed=Number(t.value)}else if(t.id==='chUV'||t.id==='chColors'){ch[t.id==='chUV'?'uv':'colors']=t.checked;chRender()}else if(t.dataset.chMix){ch.custom=t.checked?[...ch.custom,t.dataset.chMix]:ch.custom.filter(id=>id!==t.dataset.chMix)}else if(t.dataset.chGuess){ch.guess=t.checked?[...ch.guess,t.dataset.chGuess]:ch.guess.filter(id=>id!==t.dataset.chGuess)}});
document.addEventListener('keydown',e=>{let lane=e.target.closest('[data-ch-lane]');if(lane&&(e.key==='Enter'||e.key===' ')){e.preventDefault();chSpot(Number(lane.dataset.chLane))}});
document.addEventListener('click',e=>{if(page!=='chromatography')return;let spot=e.target.closest('[data-ch-spot]');if(spot&&ch.progress===1){ch.selected=spot.dataset.chSpot;chRender();return}let lane=e.target.closest('[data-ch-lane]');if(lane){chSpot(Number(lane.dataset.chLane));return}let a=e.target.closest('[data-ch-action]')?.dataset.chAction;if(!a)return;if(a.startsWith('unknown-')){chLoadUnknown(a.slice(8));return}if(a==='spot-mixture'){if(ch.progress>0||ch.spotting>=0)return;ch.sample='custom';chSpot(ch.mixLane);return}if(a==='reset'){chReset();chRender()}else if(a==='standards'&&ch.progress===0){CH_COMPOUNDS.forEach((c,i)=>ch.lanes[i]={ids:[c.id],label:c.name.slice(0,3),unknown:false});ch.message='Four dry standards occupy lanes 1–4. Spot your unknown in lane 5, then develop.';chRender()}else if(a==='demo'){chReset();CH_COMPOUNDS.forEach((c,i)=>ch.lanes[i]={ids:[c.id],label:c.name.slice(0,3),unknown:false});ch.lanes[4]={ids:[...CH_UNKNOWNS[ch.unknown]],label:'Unknown '+ch.unknown,unknown:true,unknownCode:ch.unknown};ch.sample='unknown';ch.message='Example prepared: four standards and a coded unknown on one plate. Press Develop plate to separate them.';chRender()}else if(a==='develop'){chDevelop()}else if(a==='reveal'){ch.revealed=!ch.revealed;chRender()}else if(a==='check'&&ch.progress===1){let target=CH_UNKNOWNS[ch.unknown];let ok=ch.guess.length===target.length&&target.every(id=>ch.guess.includes(id));let standards=CH_COMPOUNDS.every(c=>ch.lanes.some(l=>l&&!l.unknown&&(l.ids.length===1||l.allStandards)&&l.ids.includes(c.id)));ch.feedback=`<div class="ch-note">${ok?'Your selection matches this coded sample.':'Your selection does not match every component. Compare the number and heights of the spots, and try again.'}${!standards?' Add all four standards on a new plate for a complete same-plate comparison.':''} A matching Rf is supporting evidence; repeat with a second solvent and use co-spotting.</div>`;chRender()}else if(a==='save'&&ch.progress===1){ch.history.push({ratio:`${Math.round((1-ch.fraction)*100)}:${Math.round(ch.fraction*100)}`,unknown:ch.unknown,readings:chRows().map(r=>({lane:r.lane,label:r.label,spot:r.spot,distance:Number(r.distance.toFixed(3)),rf:Number(r.rf.toFixed(4))}))});ch.history=ch.history.slice(-12);try{localStorage.setItem('simlab-chromatography-history',JSON.stringify(ch.history))}catch{}ch.message='Run saved with solvent conditions and spot measurements.';chRender()}else if(a==='export'){let lines=[['run','hexane:ethyl acetate v/v','unknown','lane','sample','spot','spot cm','front cm','Rf (simulated)']];ch.history.forEach((r,i)=>r.readings.forEach(s=>lines.push([i+1,r.ratio,r.unknown,s.lane,s.label,s.spot,s.distance,7,s.rf])));let csv=lines.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));let link=document.createElement('a');link.href=url;link.download='SIMLAB-chromatography-runs.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});


function chLoadUnknown(code){if(!CH_UNKNOWNS[code])return;ch.unknown=code;ch.sample="unknown";ch.revealed=false;ch.guess=[];ch.feedback="";ch.message=ch.progress>0?`Unknown ${code} selected for identification. Its previously spotted lane is unchanged.`:`Unknown ${code} loaded into a fresh capillary. Choose a lane to spot it; existing samples stay in their lanes.`;chRender()}
